import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useQuery, useMutation } from '@apollo/client';
import { 
  Tabs, Tab, Box, Typography, Button, Snackbar, Alert, 
  IconButton, useTheme, useMediaQuery, Tooltip, Grid, Paper,
  Dialog, DialogActions, DialogContent, DialogTitle, Menu, MenuItem,
  FormControl, InputLabel, Select, TextField, InputAdornment
} from '@mui/material';
import { 
  Add as AddIcon, 
  Edit as EditIcon, 
  Delete as DeleteIcon,
  Logout as LogoutIcon,
  Refresh as RefreshIcon,
  Search as SearchIcon,
  FilterList as FilterListIcon,
  ViewColumn as ViewColumnIcon,
  Clear as ClearIcon,
  EventNote as EventNoteIcon,
  PendingActions as PendingActionsIcon,
  EventAvailable as EventAvailableIcon,
  CheckCircle as CheckCircleIcon
} from '@mui/icons-material';
import { format, subDays, startOfDay, endOfDay } from 'date-fns';
import { useNavigate } from 'react-router-dom';
import { useHotkeys } from 'react-hotkeys-hook';
import { useAuth } from '../../context/AuthContext';
import { 
  GET_ALL_APPOINTMENTS, 
  GET_ALL_CONTACTS, 
  CREATE_APPOINTMENT, 
  UPDATE_APPOINTMENT, 
  DELETE_APPOINTMENT, 
  UPDATE_APPOINTMENT_STATUS, 
  UPDATE_CONTACT_STATUS 
} from '../../graphql/admin';
import AppointmentForm from './AppointmentForm';
import ConfirmationDialog from '../../components/ConfirmationDialog';
import DashboardMetrics from '../../components/Dashboard/DashboardMetrics';
import DataTable from '../../components/DataTable/DataTable';

function TabPanel(props) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && (
        <Box sx={{ p: 2 }}>
          {children}
        </Box>
      )}
    </div>
  );
}

// Status options for filtering
const STATUS_OPTIONS = [
  { value: 'PENDING', label: 'Pending', color: 'warning' },
  { value: 'CONFIRMED', label: 'Confirmed', color: 'info' },
  { value: 'COMPLETED', label: 'Completed', color: 'success' },
  { value: 'CANCELLED', label: 'Cancelled', color: 'error' },
];

// Service options for filtering
const SERVICE_OPTIONS = [
  'Notary Public',
  'Mobile Notary',
  'Loan Signing Agent',
  'General Notary Work',
  'Other'
];

function AdminDashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const searchInputRef = useRef(null);

  // State for the data table
  const [searchText, setSearchText] = useState('');
  const [filters, setFilters] = useState({});
  const [selectedRows, setSelectedRows] = useState([]);
  const [currentTab, setCurrentTab] = useState(0);

  // App state
  const [appointments, setAppointments] = useState([]);
  const [contacts, setContacts] = useState([]);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [currentAppointment, setCurrentAppointment] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [appointmentToDelete, setAppointmentToDelete] = useState(null);

  // UI State
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'info'
  });

  // Date range filter
  const [dateRange, setDateRange] = useState({
    start: startOfDay(subDays(new Date(), 30)),
    end: endOfDay(new Date())
  });

  // Column visibility
  const [visibleColumns, setVisibleColumns] = useState({
    name: true,
    email: true,
    phone: true,
    service: true,
    date: true,
    status: true,
    actions: true
  });

  // Fetch data
  const { 
    loading: loadingAppointments, 
    refetch: refetchAppointments 
  } = useQuery(GET_ALL_APPOINTMENTS, {
    onCompleted: (data) => {
      setAppointments(data?.allAppointments || []);
    },
    onError: (error) => {
      console.error('Error fetching appointments:', error);
      showSnackbar(`Error loading appointments: ${error.message}`, 'error');
    },
    fetchPolicy: 'network-only'
  });

  const { 
    loading: loadingContacts, 
    refetch: refetchContacts 
  } = useQuery(GET_ALL_CONTACTS, {
    onCompleted: (data) => {
      setContacts(data?.allContacts || []);
    },
    onError: (error) => {
      console.error('Error fetching contacts:', error);
      showSnackbar(`Error loading contacts: ${error.message}`, 'error');
    },
    fetchPolicy: 'network-only'
  });

  // Mutations
  const [createAppointment] = useMutation(CREATE_APPOINTMENT, {
    onError: (error) => {
      showSnackbar(`Error creating appointment: ${error.message}`, 'error');
    }
  });

  const [updateAppointment] = useMutation(UPDATE_APPOINTMENT, {
    onError: (error) => {
      showSnackbar(`Error updating appointment: ${error.message}`, 'error');
    }
  });

  const [deleteAppointment] = useMutation(DELETE_APPOINTMENT, {
    onError: (error) => {
      showSnackbar(`Error deleting appointment: ${error.message}`, 'error');
    }
  });

  const [updateAppointmentStatus] = useMutation(UPDATE_APPOINTMENT_STATUS, {
    onError: (error) => {
      showSnackbar(`Error updating appointment status: ${error.message}`, 'error');
    }
  });

  const [updateContactStatus] = useMutation(UPDATE_CONTACT_STATUS, {
    onError: (error) => {
      showSnackbar(`Error updating contact status: ${error.message}`, 'error');
    }
  });

  const isLoading = loadingAppointments || loadingContacts;

  // Helper functions
  const showSnackbar = (message, severity = 'info') => {
    setSnackbar({
      open: true,
      message,
      severity
    });
  };

  // Event handlers
  const handleTabChange = (event, newValue) => {
    setCurrentTab(newValue);
    setSelectedRows([]);
    setSearchText('');
    setFilters({});
  };

  const handleOpenForm = (appointment = null) => {
    setCurrentAppointment(appointment);
    setIsFormOpen(true);
  };

  const handleCloseForm = () => {
    setIsFormOpen(false);
    setCurrentAppointment(null);
  };

  const handleSaveAppointment = async (appointmentData) => {
    try {
      const input = {
        ...appointmentData,
        id: appointmentData.id || undefined,
        appointmentDate: appointmentData.appointmentDate.toISOString(),
        status: appointmentData.status?.toUpperCase() || 'PENDING'
      };

      if (appointmentData.id) {
        await updateAppointment({
          variables: { input }
        });
        showSnackbar('Appointment updated successfully', 'success');
      } else {
        await createAppointment({
          variables: { input }
        });
        showSnackbar('Appointment created successfully', 'success');
      }

      await refetchAppointments();
      handleCloseForm();
    } catch (error) {
      console.error('Error saving appointment:', error);
      showSnackbar(
        `Failed to ${appointmentData?.id ? 'update' : 'create'} appointment: ${error.message}`,
        'error'
      );
    }
  };

  const handleConfirmDelete = async () => {
    if (!appointmentToDelete) return;

    try {
      await deleteAppointment({
        variables: { 
          input: { id: appointmentToDelete.id } 
        }
      });

      await refetchAppointments();
      showSnackbar('Appointment deleted successfully', 'success');
    } catch (error) {
      console.error('Error deleting appointment:', error);
      showSnackbar(`Failed to delete appointment: ${error.message}`, 'error');
    } finally {
      setDeleteDialogOpen(false);
      setAppointmentToDelete(null);
      setSelectedRows(prev => prev.filter(id => id !== appointmentToDelete.id));
    }
  };

  const handleBulkDelete = async () => {
    if (selectedRows.length === 0) return;

    try {
      await Promise.all(
        selectedRows.map(id => 
          deleteAppointment({
            variables: { input: { id } }
          })
        )
      );

      await refetchAppointments();
      showSnackbar(`Deleted ${selectedRows.length} appointments`, 'success');
      setSelectedRows([]);
    } catch (error) {
      console.error('Error deleting appointments:', error);
      showSnackbar(`Error deleting appointments: ${error.message}`, 'error');
    }
  };

  const handleStatusChange = async (id, newStatus, type) => {
    try {
      if (type === 'appointment') {
        await updateAppointmentStatus({
          variables: {
            appointmentId: id,
            status: newStatus
          }
        });

        // Update local state
        setAppointments(prev => 
          prev.map(appt => 
            appt.id === id ? { ...appt, status: newStatus } : appt
          )
        );

        showSnackbar('Appointment status updated', 'success');
      } else if (type === 'contact') {
        await updateContactStatus({
          variables: {
            contactId: id,
            status: newStatus
          }
        });

        // Update local state
        setContacts(prev => 
          prev.map(contact => 
            contact.id === id ? { ...contact, status: newStatus } : contact
          )
        );

        showSnackbar('Contact status updated', 'success');
      }
    } catch (error) {
      console.error('Error updating status:', error);
      showSnackbar(`Error updating status: ${error.message}`, 'error');
    }
  };

  const handleRefresh = async () => {
    try {
      await Promise.all([refetchAppointments(), refetchContacts()]);
      showSnackbar('Data refreshed successfully', 'success');
    } catch (error) {
      console.error('Error refreshing data:', error);
      showSnackbar(`Error refreshing data: ${error.message}`, 'error');
    }
  };

  const handleCloseSnackbar = (event, reason) => {
    if (reason === 'clickaway') return;
    setSnackbar(prev => ({ ...prev, open: false }));
  };

  // Set up keyboard shortcuts
  useHotkeys('n', (e) => {
    e.preventDefault();
    handleOpenForm();
  }, { enableOnFormTags: true });

  useHotkeys('r', (e) => {
    e.preventDefault();
    handleRefresh();
  });

  useHotkeys('ctrl+right, command+right', (e) => {
    e.preventDefault();
    setCurrentTab(prev => Math.min(prev + 1, 1));
  });

  useHotkeys('ctrl+left, command+left', (e) => {
    e.preventDefault();
    setCurrentTab(prev => Math.max(prev - 1, 0));
  });

  useHotkeys('esc', () => {
    if (isFormOpen) handleCloseForm();
    if (deleteDialogOpen) setDeleteDialogOpen(false);
  });

  // ... rest of the component code (JSX) ...

  return (
    <Box sx={{ width: '100%', p: 3 }}>
      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleCloseSnackbar} 
          severity={snackbar.severity}
          sx={{ width: '100%' }}
          variant="filled"
        >
          {snackbar.message}
        </Alert>
      </Snackbar>

      {/* Main content */}
      <Box sx={{ mb: 3 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h4" component="h1">
            Admin Dashboard
          </Typography>
          <Box>
            <Button
              variant="contained"
              color="primary"
              startIcon={<AddIcon />}
              onClick={() => handleOpenForm()}
              sx={{ minWidth: 180 }}
            >
              New Appointment
            </Button>
          </Box>
        </Box>

        {/* Tabs */}
        <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
          <Tabs 
            value={currentTab} 
            onChange={handleTabChange} 
            aria-label="dashboard tabs"
            variant="scrollable"
            scrollButtons="auto"
          >
            <Tab label={`Appointments (${appointments.length})`} />
            <Tab label={`Messages (${contacts.length})`} />
          </Tabs>
        </Box>

        {/* Tab Panels */}
        <TabPanel value={currentTab} index={0}>
          <DataTable
            columns={[
              // Define your columns here
            ]}
            data={appointments}
            onRowClick={(e, row) => handleOpenForm(row)}
            onEdit={handleOpenForm}
            onDelete={(row) => {
              setAppointmentToDelete(row);
              setDeleteDialogOpen(true);
            }}
            onRefresh={handleRefresh}
            onSelectionChange={handleRowSelect}
            loading={loadingAppointments}
            searchText={searchText}
            onSearchChange={setSearchText}
            selectedRows={selectedRows}
            onBulkAction={handleBulkDelete}
            bulkActions={[
              {
                label: 'Delete Selected',
                action: handleBulkDelete,
                color: 'error',
                icon: <DeleteIcon />
              },
              {
                label: 'Mark as Pending',
                action: () => handleBulkStatusUpdate('PENDING'),
                color: 'warning',
                icon: <PendingActionsIcon />
              },
              {
                label: 'Mark as Confirmed',
                action: () => handleBulkStatusUpdate('CONFIRMED'),
                color: 'info',
                icon: <EventAvailableIcon />
              },
              {
                label: 'Mark as Completed',
                action: () => handleBulkStatusUpdate('COMPLETED'),
                color: 'success',
                icon: <CheckCircleIcon />
              },
              {
                label: 'Mark as Cancelled',
                action: () => handleBulkStatusUpdate('CANCELLED'),
                color: 'error',
                icon: <ClearIcon />
              }
            ]}
          />
        </TabPanel>

        <TabPanel value={currentTab} index={1}>
          <DataTable
            columns={[
              // Define your contact columns here
            ]}
            data={contacts}
            title="Contact Messages"
            searchText={searchText}
            onSearchChange={setSearchText}
            onRefresh={handleRefresh}
            loading={loadingContacts}
          />
        </TabPanel>
      </Box>

      {/* Appointment Form Dialog */}
      <AppointmentForm 
        open={isFormOpen}
        onClose={handleCloseForm}
        appointment={currentAppointment}
        onSave={handleSaveAppointment}
      />

      {/* Delete Confirmation Dialog */}
      <ConfirmationDialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onConfirm={handleConfirmDelete}
        title="Delete Appointment"
        content="Are you sure you want to delete this appointment? This action cannot be undone."
      />
    </Box>
  );
}

export default AdminDashboard;
